@Bean
public Queue mainQueue() {
    return QueueBuilder.durable("ecommerce.orders")
        .withArgument("x-dead-letter-exchange", "dlx.exchange") // Route failures here
        .withArgument("x-dead-letter-routing-key", "dlq.orders")
        // Drop message after 3 retries from DLX
        .withArgument("x-message-ttl", 60000) 
        .build();
}

@RabbitListener(queues = "ecommerce.orders")
public void processOrder(Message msg, Channel channel) throws IOException {
    try {
        process(msg);
        channel.basicAck(msg.getMessageProperties().getDeliveryTag(), false);
    } catch (FatalException e) {
        // basicReject with requeue=false triggers the Dead Letter Exchange routing
        channel.basicReject(msg.getMessageProperties().getDeliveryTag(), false);
    }
}

